<section class="mt-8 rounded-2xl border border-slate-200 bg-white p-6 shadow-card"><h2 class="text-lg font-bold">Problema reportado</h2><p class="mt-2 text-sm text-slate-600">Por <?= $e($request['requester_name']) ?> · <?= $e($localDate($request['created_at'])) ?></p><p class="mt-4 whitespace-pre-wrap break-words leading-7 text-slate-700"><?= $e($request['description']) ?></p></section>
<section class="mt-5 rounded-2xl border border-slate-200 bg-white p-6 shadow-card"><h2 class="text-lg font-bold">Evidencias</h2><?php if ($detail['attachments'] === []): ?><p class="mt-2 text-slate-600">No se adjuntaron archivos.</p><?php else: ?><ul class="mt-3 space-y-2"><?php foreach ($detail['attachments'] as $attachment): ?><li><a href="/technician/attachments/<?= (int) $attachment['id'] ?>" class="inline-flex min-h-11 items-center break-all font-semibold text-institutional-700 underline"><?= $e($attachment['original_name']) ?></a></li><?php endforeach; ?></ul><?php endif; ?></section>
