 ?></button></form></section><?php else: ?><section class="mt-5 rounded-2xl border border-institutional-100 bg-institutional-50 p-6"><h2 class="text-lg font-bold">Atención finalizada</h2><?php if ($request['solution'] !== null): ?><p class="mt-3 whitespace-pre-wrap break-words text-slate-700"><?= $e($request['solution']) ?></p><?php endif; ?></section><?php endif; ?><?php require __DIR__ . '/partials/case-tasks.php'; ?><?php require __DIR__ . '/partials/request-history.php'; ?></main></body></html>
